DataCalcInsightTemplate.expression:
SELECT {Source:GenAIGatewayRequest__dlm}.{Source_Field:promptTemplateDevName__c} AS {CI_Target_Field:prompt_template__c}, {Source:GenAIFeedback__dlm}.{Source_Field:feedback__c} AS {CI_Target_Field:feedback__c}, COUNT({Source:GenAIFeedback__dlm}.{Source_Field:feedback__c}) AS {CI_Target_Field:counts__c}
FROM {Source:GenAIFeedback__dlm} 
    FULL OUTER JOIN {Source:GenAIGeneration__dlm} ON ({Source:GenAIFeedback__dlm}.{Source_Field:generationId__c} = {Source:GenAIGeneration__dlm}.{Source_Field:generationId__c}) 
    FULL OUTER JOIN {Source:GenAIGatewayResponse__dlm} ON ({Source:GenAIGeneration__dlm}.{Source_Field:generationResponseId__c} = {Source:GenAIGatewayResponse__dlm}.{Source_Field:generationResponseId__c}) 
    FULL OUTER JOIN {Source:GenAIGatewayRequest__dlm} ON ({Source:GenAIGatewayResponse__dlm}.{Source_Field:generationRequestId__c} = {Source:GenAIGatewayRequest__dlm}.{Source_Field:gatewayRequestId__c})
WHERE {Source:GenAIGatewayRequest__dlm}.{Source_Field:promptTemplateDevName__c}  IS NOT NULL
GROUP BY {Source_Field:prompt_template__c}, {Source_Field:feedback__c}
